// Package libm builds the math functions of the engine's own small libc
// (engine/libc of liustack/quickjs: musl's libm at a pinned commit, with the
// patches of upstream), so that Math.* gives the bits upstream records on
// amd64 and arm64. TinyGo's wasi-libc has no libm. The C files here are
// generated by scripts/vendor-engine.sh.
package libm

/*
// relative -I paths: TinyGo 0.44 resolves ${SRCDIR}/.. to ${SRCDIR} itself
#cgo CFLAGS: -I../../../third_party/quickjs-engine/libc -I../../../third_party/quickjs-engine/libc/internal
#cgo CFLAGS: -O2 -fno-stack-protector -fwrapv -fno-math-errno -ffp-contract=off
#cgo CFLAGS: -Wno-unused-but-set-variable -Wno-unused-variable -Wno-shift-op-parentheses -Wno-parentheses -Wno-dangling-else
*/
import "C"
